import os
from dataclasses import dataclass
from typing import Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class EnvelopeEncryptionError(Exception):
    pass


@dataclass
class EncryptedPayload:
    ciphertext_blob: bytes
    encrypted_data_key: bytes
    key_id: str
    encryption_context: Optional[dict] = None


class KmsEnvelopeEncryptor:
    def __init__(self, key_id: str, region_name: Optional[str] = None):
        self.key_id = key_id
        self.kms = boto3.client("kms", region_name=region_name)

    def generate_data_key(self, encryption_context: Optional[dict] = None) -> tuple[bytes, bytes]:
        try:
            kwargs = {"KeyId": self.key_id, "KeySpec": "AES_256"}
            if encryption_context:
                kwargs["EncryptionContext"] = encryption_context
            response = self.kms.generate_data_key(**kwargs)
            return response["Plaintext"], response["CiphertextBlob"]
        except (BotoCoreError, ClientError) as e:
            raise EnvelopeEncryptionError(f"Failed to generate data key: {e}") from e

    @staticmethod
    def _xor_stream(data: bytes, key: bytes) -> bytes:
        return bytes(b ^ key[i % len(key)] for i, b in enumerate(data))

    def encrypt(self, plaintext: bytes, encryption_context: Optional[dict] = None) -> EncryptedPayload:
        data_key_plaintext, data_key_encrypted = self.generate_data_key(encryption_context=encryption_context)
        ciphertext = self._xor_stream(plaintext, data_key_plaintext)
        return EncryptedPayload(
            ciphertext_blob=ciphertext,
            encrypted_data_key=data_key_encrypted,
            key_id=self.key_id,
            encryption_context=encryption_context,
        )

    def decrypt(self, payload: EncryptedPayload) -> bytes:
        try:
            kwargs = {"CiphertextBlob": payload.encrypted_data_key}
            if payload.encryption_context:
                kwargs["EncryptionContext"] = payload.encryption_context
            response = self.kms.decrypt(**kwargs)
            data_key_plaintext = response["Plaintext"]
            return self._xor_stream(payload.ciphertext_blob, data_key_plaintext)
        except (BotoCoreError, ClientError) as e:
            raise EnvelopeEncryptionError(f"Failed to decrypt data key: {e}") from e


def encrypt_bytes(plaintext: bytes, key_id: str, encryption_context: Optional[dict] = None, region_name: Optional[str] = None) -> EncryptedPayload:
    return KmsEnvelopeEncryptor(key_id=key_id, region_name=region_name).encrypt(plaintext, encryption_context=encryption_context)


def decrypt_bytes(payload: EncryptedPayload, region_name: Optional[str] = None) -> bytes:
    return KmsEnvelopeEncryptor(key_id=payload.key_id, region_name=region_name).decrypt(payload)


if __name__ == "__main__":
    kms_key_id = os.environ.get("AWS_KMS_KEY_ID", "")
    if not kms_key_id:
        raise SystemExit("Set AWS_KMS_KEY_ID to a valid KMS key ARN or alias.")

    region = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION")
    context = {"purpose": "envelope-encryption"}

    plaintext = b"secret message"
    payload = encrypt_bytes(plaintext, key_id=kms_key_id, encryption_context=context, region_name=region)
    recovered = decrypt_bytes(payload, region_name=region)

    assert recovered == plaintext
